import mapboxgl from 'mapbox-gl';
import * as THREE from 'three'

import { AppHypercubeMap } from '../AppHypercubeMap';
import { Hypercube3D } from '../Scene/Hypercube3D';

import { convertGroupToInstanced } from '../utils/ThreeUtils'

export class RendererThreeMapbox {
	public app: AppHypercubeMap;
	public map: mapboxgl.Map;

	private scene!: THREE.Scene;
	private camera!: THREE.PerspectiveCamera;
	private renderer!: THREE.WebGLRenderer;
	private cube!: THREE.Mesh;
	private cube2!: THREE.Mesh;

	public modelTransform = {};
	public angle = 0;

	public target = { lng: 144.7937, lat: 13.4443 };

	public cubes: THREE.Mesh[] = [];

	public hypercube3D: Hypercube3D;

	private raycaster = new THREE.Raycaster();
	private mouse = new THREE.Vector2();
	private selectedObject: THREE.Mesh | null = null;

	private mercBase: mapboxgl.MercatorCoordinate;
	private lastProjectionMatrix: THREE.Matrix4 | null = null;

	constructor(app: AppHypercubeMap, map: mapboxgl.Map) {
		this.app = app;
		this.map = map;

		this.initHypercube3D()
	}
	public async initHypercube3D() {
		this.hypercube3D = await this.app.scene.initHypercube3D();

		this.scene.add(this.hypercube3D.mesh);

		const scaleModel = 0.001

		// const mercA = 
		const altitude = 10;
		for (let i = 0; i < this.app.config.locations.length; i++) {
			// const clone = this.hypercube3D.meshs.clone(true);
			const clone = convertGroupToInstanced(this.hypercube3D.mesh)
			const [lngA, latA] = this.app.config.locations[i];
			const mercA = mapboxgl.MercatorCoordinate.fromLngLat([lngA, latA], altitude);

			const scale = this.mercBase.meterInMercatorCoordinateUnits();
			// const mercA = mapboxgl.MercatorCoordinate.fromLngLat([lngA, latA], altitude);

			clone.position.set(
				(mercA.x - this.mercBase.x) / scale,
				0,
				(mercA.y - this.mercBase.y) / scale,
			);
			clone.scale.set(scaleModel, scaleModel, scaleModel)
			clone.rotateY(-90)
			this.scene.add(clone);
		}

		// console.log('111')
	}
	public createLayer(): mapboxgl.CustomLayerInterface {
		const layer: mapboxgl.CustomLayerInterface = {
			id: "threejs-layer-guam",
			type: "custom",
			renderingMode: "3d",

			onAdd: (map, gl) => {


				// console.log('2222')
				this.scene = new THREE.Scene();
				this.scene.background = null;

				// create two three.js lights to illuminate the model
				const directionalLight = new THREE.DirectionalLight(0xffffff);
				directionalLight.position.set(0, -70, 100).normalize();
				this.scene.add(directionalLight);

				const directionalLight2 = new THREE.DirectionalLight(0xffffff);
				directionalLight2.position.set(0, 70, 100).normalize();
				this.scene.add(directionalLight2);


				const lng = this.target.lng;
				const lat = this.target.lat;
				const altitude = 10;
				const cubeSize = 200
				const color = 0xfafafa;

				const mercBase = mapboxgl.MercatorCoordinate.fromLngLat([lng, lat], altitude);
				this.mercBase = mercBase;
				const scale = mercBase.meterInMercatorCoordinateUnits();

				const geometry = new THREE.BoxGeometry(cubeSize, cubeSize, cubeSize);
				const material = new THREE.MeshStandardMaterial({
					color: color,
					metalness: 0.3,
					roughness: 0.7,
				});
				this.cube = new THREE.Mesh(geometry, material);
				this.cube.position.set(mercBase.x, mercBase.y, mercBase.z);
				// this.scene.add(this.cube);


				for (let i = 0; i < this.app.config.locations.length; i++) {
					const [lngA, latA] = this.app.config.locations[i];
					const mercA = mapboxgl.MercatorCoordinate.fromLngLat([lngA, latA], altitude);

					const cubeMaterial = new THREE.MeshStandardMaterial({
						color: 0x88ccff,
						metalness: 0.3,
						roughness: 0.7,
					});

					const cubeInstance = new THREE.Mesh(geometry, cubeMaterial);
					cubeInstance.position.set(
						(mercA.x - mercBase.x) / scale,
						0,
						(mercA.y - mercBase.y) / scale,
					);

					cubeInstance.userData = { node: this.app.scene.graphHypercube.nodes[i] }
					this.app.scene.graphHypercube.nodes[i].mesh = cubeInstance;
					// this.scene.add(cubeInstance);
					this.cubes.push(cubeInstance);
				}


				this.camera = new THREE.PerspectiveCamera(75, map.getCanvas().width / map.getCanvas().height, 0.0001, 1000);
				this.camera.position.set(mercBase.x, mercBase.y, mercBase.z + 200 * scale);
				this.camera.lookAt(this.cube.position);

				this.renderer = new THREE.WebGLRenderer({
					canvas: map.getCanvas(),
					context: gl,
					antialias: true,
				});
				this.renderer.autoClear = false;



				const modelOrigin = [144.7937, 13.4443];
				const modelAltitude = 0;
				const modelRotate = [Math.PI / 2, 0, 0];

				const modelAsMercatorCoordinate = mapboxgl.MercatorCoordinate.fromLngLat(modelOrigin, modelAltitude);

				this.modelTransform = {
					translateX: modelAsMercatorCoordinate.x,
					translateY: modelAsMercatorCoordinate.y,
					translateZ: modelAsMercatorCoordinate.z,
					rotateX: modelRotate[0],
					rotateY: modelRotate[1],
					rotateZ: modelRotate[2],
					scale: modelAsMercatorCoordinate.meterInMercatorCoordinateUnits(),
				};

				map.on('click', (e) => this.onMapClick(e));

			},
			render: (gl, matrix) => {
				// transformation parameters to position, rotate and scale the 3D model onto the map
				const rotationX = new THREE.Matrix4().makeRotationAxis(
					new THREE.Vector3(1, 0, 0),
					this.modelTransform.rotateX
				);
				const rotationY = new THREE.Matrix4().makeRotationAxis(
					new THREE.Vector3(0, 1, 0),
					this.modelTransform.rotateY
				);
				const rotationZ = new THREE.Matrix4().makeRotationAxis(
					new THREE.Vector3(0, 0, 1),
					this.modelTransform.rotateZ
				);

				const m = new THREE.Matrix4().fromArray(matrix);
				const l = new THREE.Matrix4()
					.makeTranslation(
						this.modelTransform.translateX,
						this.modelTransform.translateY,
						this.modelTransform.translateZ
					)
					.scale(
						new THREE.Vector3(
							this.modelTransform.scale,
							-this.modelTransform.scale,
							this.modelTransform.scale
						)
					)
					.multiply(rotationX)
					.multiply(rotationY)
					.multiply(rotationZ);

				this.camera.projectionMatrix = m.multiply(l);

				// 픽킹을 위해 projectionMatrix 저장
				this.lastProjectionMatrix = this.camera.projectionMatrix.clone();

				// this.cube.rotation.y += 0.01;
				// this.cube2.rotation.x += 0.01;
				for (const cube of this.cubes) {
					cube.rotation.y += 0.01;
				}

				this.renderer.resetState();
				this.renderer.render(this.scene, this.camera);
				this.map.triggerRepaint();

				// this.cameraRotate();
			},
		};

		return layer;
	}

	public cameraRotate() {
		this.angle = (this.angle + 0.2) % 360;
		const radius = 0.003;

		const rad = this.angle * Math.PI / 180;
		const lng = this.target.lng + radius * Math.cos(rad);
		const lat = this.target.lat + radius * Math.sin(rad);

		this.map.jumpTo({
			center: [lng, lat],
			bearing: (this.angle + 180) % 360,
			pitch: 75,
			zoom: 14.5,
		});
	}

	private onMapClick(e: mapboxgl.MapMouseEvent & mapboxgl.EventData) {
		const clickedMerc = mapboxgl.MercatorCoordinate.fromLngLat(
			[e.lngLat.lng, e.lngLat.lat], 10 // altitude
		);

		const mercBase = this.mercBase
		const scale = mercBase.meterInMercatorCoordinateUnits();

		let closestCube: THREE.Mesh | null = null;
		let minDistance = Infinity;

		for (const cube of this.cubes) {
			const cubeWorldPos = new THREE.Vector3();
			cube.getWorldPosition(cubeWorldPos);


			const cubeMercX = mercBase.x + cubeWorldPos.x * scale;
			const cubeMercY = mercBase.y + cubeWorldPos.z * scale;

			const dx = clickedMerc.x - cubeMercX;
			const dy = clickedMerc.y - cubeMercY;
			const distance = Math.sqrt(dx * dx + dy * dy);

			if (distance < minDistance) {
				minDistance = distance;
				closestCube = cube;
			}
		}

		const threshold = 0.00001;
		if (closestCube && minDistance < threshold) {
			if (this.selectedObject && this.selectedObject !== closestCube) {
				(this.selectedObject.material as THREE.MeshStandardMaterial).color.set(0x88ccff);
			}
			if (this.selectedObject) {
				this.selectedObject.userData.node.isSelected = false
			}
			this.selectedObject = closestCube;
			(closestCube.material as THREE.MeshStandardMaterial).color.set(0xff5555);
			const index = this.cubes.indexOf(this.selectedObject);
			this.selectedObject.userData.node.isSelected = true;
			console.log(index, closestCube.position);

		} else {

			// console.log('ee')

			this.app.scene.graphHypercube.addCube(e.lngLat.lng, e.lngLat.lat)
			this.app.scene.graphHypercube.buildEdge()
		}
	}

}