import { AppHypercubeMap } from '../AppHypercubeMap';
import { ThemeMode, ColorBlending } from '../utils/const';

export class Controller {
	public divHost: HTMLDivElement;

	public app: AppHypercubeMap;

	private viewMode = 0

	constructor(app: AppHypercubeMap) {
		this.app = app;

	}
	public toggleView(): void {
		if (this.viewMode++ % 2 === 0) {
			this.app.mapboxWrapper.toPerspective()
		} else {
			this.app.mapboxWrapper.toTop()
		}
		// console.log('toggle view');
	}
	public setCircleRadius(radius: number): void {
		this.app.scene.graphHypercube.setCircleRadius(radius);
	}
	public toggleHypercube() {
		this.app.scene.toggleHypercube()
	}
	public toggleMode(): void {
		if (this.app.mapboxWrapper.modeDark) {
			this.app.mode = ThemeMode.Light;
			this.app.rendererCanvas.modeBlending = ColorBlending.Multiply;
		} else {
			this.app.mode = ThemeMode.Dark;
			this.app.rendererCanvas.modeBlending = ColorBlending.ColorDodge;
		}

		// console.log(this.app.mode)
		this.app.mapboxWrapper.modeDark = !this.app.mapboxWrapper.modeDark;
		this.app.scene.updateTheme();
	}
	public animationCamera() {
		this.app.scene.animationCamera();
	}
}