import { Scene } from '..'
import { ThemeMode } from '../../utils/const'

export class Theme {
	public scene: Scene;

	colorHypercubeDash = '#00ff00';
	colorHypercubeDashFill = 'rgba(0, 255, 0, 0.1)';

	private listeners: ((key: string, value: string) => void)[] = [];

	constructor(scene: Scene) {
		this.scene = scene;
		this.applyTheme();
	}

	public applyTheme(): void {
		this.colorHypercubeDash = this.scene.app.mode === ThemeMode.Dark ? '#00ff00' : '#0066CC';
		this.colorHypercubeDashFill = this.scene.app.mode === ThemeMode.Dark ? 'rgba(0, 255, 0, 0.3)' : 'rgba(0, 0, 255, 0.3)';

		this.notifyChange('colorHypercubeDashFill', this.colorHypercubeDashFill);
		this.notifyChange('colorHypercubeDash', this.colorHypercubeDash);
	}

	public onChange(listener: (key: string, value: string) => void) {
		this.listeners.push(listener);
	}

	private notifyChange(key: string, value: string) {
		this.listeners.forEach(listener => listener(key, value));
	}
}
