import { HypercubeNode } from "./HypercubeNode";
import { Scene } from '..'

export class HypercubeGraph {
	public scene: Scene;
	public nodes: HypercubeNode[] = [];
	public edges: HypercubeNode[][] = [];

	public showHypercubeStatus: boolean = false;

	private radius = 500

	constructor(scene: Scene) {
		this.scene = scene;
	}
	public addCube(lng: number, lat: number) {
		const hcNode = new HypercubeNode(this, [lng, lat]);
		hcNode.radius = this.radius;
		this.nodes.push(hcNode);
	}
	public setCircleRadius(radius: number): void {
		this.radius = radius;
		this.nodes.forEach(node => {
			node.radius = radius;
		})
	}
	public buildEdge(k: number = 3) {
		this.edges = [];

		this.nodes.forEach(node => node.neighborNodes = []);

		for (let i = 0; i < this.nodes.length; i++) {
			const nodeA = this.nodes[i];

			const distances = this.nodes
				.map((nodeB, j) => {
					if (i === j) return null;
					const dx = nodeA.pt[0] - nodeB.pt[0];
					const dy = nodeA.pt[1] - nodeB.pt[1];
					const dist = Math.sqrt(dx * dx + dy * dy);
					return { nodeB, dist };
				})
				.filter(Boolean)
				.sort((a, b) => a!.dist - b!.dist)
				.slice(0, k);

			for (const { nodeB } of distances) {
				if (!nodeB) continue;
				if (!this.isEdgeExist(nodeA, nodeB)) {
					this.edges.push([nodeA, nodeB]);
				}

				if (!nodeA.neighborNodes.includes(nodeB))
					nodeA.neighborNodes.push(nodeB);
				if (!nodeB.neighborNodes.includes(nodeA))
					nodeB.neighborNodes.push(nodeA);
			}
		}
	}

	private isEdgeExist(a: HypercubeNode, b: HypercubeNode): boolean {
		return this.edges.some(
			([n1, n2]) => (n1 === a && n2 === b) || (n1 === b && n2 === a)
		);
	}
	public render(ctx: CanvasRenderingContext2D) {

		if (this.showHypercubeStatus) {
			for (let i = 0; i < this.nodes.length; ++i) {
				const node = this.nodes[i];
				node.render(ctx);
			}
		}

		for (let i = 0; i < this.edges.length; ++i) {
			const edge = this.edges[i]
			ctx.lineWidth = 0.5
			ctx.beginPath();

			let pos = this.scene.app.mapboxWrapper.toScreen(edge[0].pt[0], edge[0].pt[1]);
			ctx.moveTo(pos[0], pos[1])

			pos = this.scene.app.mapboxWrapper.toScreen(edge[1].pt[0], edge[1].pt[1]);
			ctx.lineTo(pos[0], pos[1])
			ctx.stroke();

			// console.log(edge[0].pt[0], edge[0].pt[1])
		}



	}
}

