	public init() {
		// console.log('init scene');

		// console.log(this.app.config.locations)

		for (let i = 0; i < this.app.config.locations.length; ++i) {
			const pt = this.app.config.locations[i];
			this.addCube(pt[0], pt[1]);
		}
		this.graphHypercube.buildEdge();

		this.initLayer()
	}
	public addCube(lng: number, lat: number) {
		this.graphHypercube.addCube(lng, lat);
	}
	public toggleHypercube() {
		this.graphHypercube.showHypercubeStatus = !this.graphHypercube.showHypercubeStatus;
	}
	public render(ctx: CanvasRenderingContext2D) {

		if (this.isCameraAnimated) {
			this.app.mapboxWrapper.rotateAndMove();
		}

		this.graphHypercube?.render(ctx);

		if (this.showDelaunay || this.showVoronoi) {
			const data = []
			for (let i = 0; i < this.graphHypercube.nodes.length; ++i) {
				const node = this.graphHypercube.nodes[i];
				data.push({ x: node.pt[0], y: node.pt[1] });
			}

			// console.log('data', data);
			this.renderDelaunayTriangulation(ctx, data);
		}

	}
	public renderDelaunayTriangulation(ctx: CanvasRenderingContext2D, data: number[][]) {

		if (data.length >= 3) {
			this.delaunay = new DelaunayTriangulation();
			const triangles = this.delaunay.triangulate(data);
			// console.log(data, triangles)


			if (this.showVoronoi) {
				const voronoiPolygons = this.delaunay.computeVoronoi(data);

				ctx.lineWidth = 2;

				for (let i = 0; i < voronoiPolygons.length; i++) {
					const polygon = voronoiPolygons[i];

					const hue = (i * 137.508) % 360;
					ctx.fillStyle = `hsla(${hue}, 70%, 85%, 0.5)`;
					ctx.strokeStyle = `hsl(${hue}, 70%, 50%)`;

					ctx.beginPath();
					if (polygon.vertices.length > 0) {

						let p0 = this.app.mapboxWrapper.toScreen(polygon.vertices[0].x, polygon.vertices[0].y);
						ctx.moveTo(p0[0], p0[1]);
						// ctx.moveTo(polygon.vertices[0].x, polygon.vertices[0].y);

						for (let j = 1; j < polygon.vertices.length; j++) {

							p0 = this.app.mapboxWrapper.toScreen(polygon.vertices[j].x, polygon.vertices[j].y);
							ctx.lineTo(p0[0], p0[1]);

							// ctx.lineTo(polygon.vertices[j].x, polygon.vertices[j].y);
						}
						ctx.closePath();
						ctx.fill();
						ctx.stroke();
					}
				}
			}

			ctx.setLineDash([0, 0]);
			if (this.showDelaunay) {
				ctx.strokeStyle = '#007bff55';
				ctx.lineWidth = 0.5;

				for (const triangle of triangles) {
					ctx.beginPath();

					const p0 = this.app.mapboxWrapper.toScreen(triangle[0].x, triangle[0].y);
					ctx.moveTo(p0[0], p0[1]);


					const p1 = this.app.mapboxWrapper.toScreen(triangle[1].x, triangle[1].y);
					ctx.lineTo(p1[0], p1[1]);

					const p2 = this.app.mapboxWrapper.toScreen(triangle[2].x, triangle[2].y);
					ctx.lineTo(p2[0], p2[1]);

					ctx.closePath();
					ctx.stroke();
				}
			}

			ctx.fillStyle = '#dc3545';
			ctx.strokeStyle = '#fff';
			ctx.lineWidth = 2;

			for (const point of data) {
				ctx.beginPath();
				// @ts-ignore
				ctx.arc(point.x, point.y, 6, 0, 2 * Math.PI);
				ctx.fill();
				ctx.stroke();
			}
		}
	}
