export const adjustHexBrightness = (hex: string, brightness: number): string => {
	hex = hex.replace(/^#/, "");

	if (hex.length === 3) {
		hex = hex.split("").map(x => x + x).join("");
	}

	const r = parseInt(hex.substring(0, 2), 16);
	const g = parseInt(hex.substring(2, 4), 16);
	const b = parseInt(hex.substring(4, 6), 16);

	const newR = Math.min(255, Math.max(0, r * brightness));
	const newG = Math.min(255, Math.max(0, g * brightness));
	const newB = Math.min(255, Math.max(0, b * brightness));

	const toHex = (v: number) => Math.round(v).toString(16).padStart(2, "0");
	return `#${toHex(newR)}${toHex(newG)}${toHex(newB)}`;
}
export const blendColorByMode = (
	color: string,
	mode: "light" | "dark" = "light"
): string => {
	let r: number, g: number, b: number, a = 1;

	if (color.startsWith("#")) {
		color = color.replace(/^#/, "");
		if (color.length === 3) color = color.split("").map(x => x + x).join("");
		r = parseInt(color.substring(0, 2), 16);
		g = parseInt(color.substring(2, 4), 16);
		b = parseInt(color.substring(4, 6), 16);
	}

	else if (color.startsWith("rgba")) {
		const match = color.match(/rgba?\(([^)]+)\)/);
		if (match) {
			const parts = match[1].split(",").map(v => parseFloat(v.trim()));
			[r, g, b, a = 1] = parts;
		} else throw new Error("Invalid RGBA format");
	}

	else if (color.startsWith("rgb")) {
		const match = color.match(/rgb\(([^)]+)\)/);
		if (match) {
			const parts = match[1].split(",").map(v => parseFloat(v.trim()));
			[r, g, b] = parts;
		} else throw new Error("Invalid RGB format");
	} else {
		throw new Error("Unsupported color format");
	}

	const multiply = (c: number, bg: number) => (c * bg) / 255;
	const screen = (c: number, bg: number) => 255 - ((255 - c) * (255 - bg)) / 255;

	let nr: number, ng: number, nb: number;
	if (mode === "light") {
		const bg = 238;
		nr = multiply(r, bg);
		ng = multiply(g, bg);
		nb = multiply(b, bg);
	} else {
		const bg = 34;
		nr = screen(r, bg);
		ng = screen(g, bg);
		nb = screen(b, bg);
	}

	return `rgba(${Math.round(nr)}, ${Math.round(ng)}, ${Math.round(nb)}, ${a})`;
}

