		// console.log(ctx);

		// this.graph.scene.app.rendererCanvas.renderCircle(ctx, this.pt[0], this.pt[1], this.radius);


		// ...... start dash
		ctx.beginPath();
		ctx.lineDashOffset = this.time * 20
		ctx.setLineDash([1, 8]);
		ctx.moveTo(0, 50);
		ctx.lineTo(300, 50);
		ctx.lineWidth = 1.5;

		const path = this.graph.scene.app.rendererCanvas.drawPathPerspectiveCircle(ctx, this.pt[0], this.pt[1], this.radius, 32);
		ctx.fillStyle = this.graph.scene.theme.colorHypercubeDashFill
		// ctx.fill(path);
		ctx.strokeStyle = this.graph.scene.theme.colorHypercubeDash
		ctx.stroke(path);
		// ...... end dash



		ctx.beginPath();
		ctx.setLineDash([0, 0]);
		ctx.lineWidth = .5;
		const baseRadius = this.isSelected ? this.radius * 2 : Math.sin(this.time) * this.radius * 0.5
		// console.log(baseRadius)
		const pathA = this.graph.scene.app.rendererCanvas.drawPathPerspectiveCircle(ctx, this.pt[0], this.pt[1], baseRadius, 32);
		if (this.isSelected) {
			ctx.fillStyle = '#ffff0055'
		}
		ctx.fill(pathA);
		ctx.stroke(pathA);


