import * as THREE from 'three';


export const convertGroupToInstanced = (
	group: THREE.Group,
	instancePositions?: THREE.Vector3[]
): THREE.Group => {
	const instancedGroup = new THREE.Group();
	const dummy = new THREE.Object3D();

	const positions =
		instancePositions && instancePositions.length > 0
			? instancePositions
			: [new THREE.Vector3(0, 0, 0)];

	group.traverse(obj => {
		if (obj instanceof THREE.Mesh) {
			const geometry = obj.geometry;
			const material = obj.material;
			const count = positions.length;

			const instancedMesh = new THREE.InstancedMesh(geometry, material, count);

			for (let i = 0; i < count; i++) {
				const basePos = positions[i];

				dummy.position.copy(basePos.clone().add(obj.position));
				dummy.rotation.copy(obj.rotation);
				dummy.scale.copy(obj.scale);
				dummy.updateMatrix();

				instancedMesh.setMatrixAt(i, dummy.matrix);
			}

			instancedMesh.instanceMatrix.needsUpdate = true;
			instancedGroup.add(instancedMesh);
		}
	});

	return instancedGroup;
}
